import{z as n,x as B,o as s,c as p,q as r,j as l,D as e,d as t,s as i,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"logit 处理器栈的设计","description":"","frontmatter":{"title":"logit 处理器栈的设计","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dec-logit-processor-stack.md","filePath":"llm/dec-logit-processor-stack.md","lastUpdated":1791063341000}'),d={name:"llm/dec-logit-processor-stack.md"};function m(g,a,f,c,C,b){const o=B("Mermaid");return s(),p("div",null,[a[2]||(a[2]=r('<h1 id="logit-处理器栈的设计" tabindex="-1">logit 处理器栈的设计 <a class="header-anchor" href="#logit-处理器栈的设计" aria-label="Permalink to &quot;logit 处理器栈的设计&quot;">​</a></h1><div class="epigraph"><p>每一步 logits 都该有唯一的责任人：栈不是插件袋，是一份按位置索引的契约。</p><footer>—— 据 Transformers 的 LogitsProcessorList 与 vLLM 等引擎采样钩子的接口约定整理</footer></div><p><a href="/llm/dec-multi-constraint">上一课</a>把多条约束并成每步的一个合法集。服务上这些操作不是请求临场拼出来的，而是每个请求带一根<strong>处理器栈</strong>：采样参数、惩罚、bias、掩码按固定次序串在采样前。机制零件基础课都给过了——<a href="/llm/ngram-blocking">n-gram 阻断</a>、<a href="/llm/logit-bias">logit bias</a>、<a href="/llm/sampling-temperature-topp">温度与截断</a>、约束掩码。本课写服务侧：栈的契约、实例化、批量分派与回归。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每请求的栈不同：A 请求要 JSON 文法加禁词，B 请求要低温加重复惩罚，C 请求什么都不带。连续批里 \\(B\\) 条序列并行 decode，每步都要对各自的 logits 施各自的栈——掩码必须按序列（<a href="/llm/constrained-decoding">约束解码课</a>的老结论），bias 是每请求的稀疏对，惩罚是每请求的<strong>有状态</strong>对象。把栈写成 <code>if json then ...</code> 的分支袋，结果是：顺序随实现漂移、状态挂错请求、评测与线上行为分叉。缺口是一份显式契约：每个处理器声明它对 logits 做什么、是否携带状态、必须排在哪。</p><p><span class="marginnote">术语翻译：logits 就是模型对词表里每个 token 打出的原始分数（几万个浮点数），还没变成概率。处理器栈就是在「原始分数 → 采样」之间插入的一串加工步骤：有的把非法选项的分数改成负无穷（等于禁掉），有的加减分数（偏置与惩罚），有的把分数整体除以温度。栈 = 这串步骤的固定排队顺序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>操作分类与固定次序。</strong> 每个处理器声明三类之一：mask（把非法位置置 \\(-\\infty\\)，如文法、n-gram）、affine（逐 token 加减，如 bias、重复与频率惩罚）、scaler（温度）或 truncator（top-\\(k\\) / top-\\(p\\)）。次序钉死：mask 族 → affine 族 → 温度 → 截断 → 采样。理由在机制上：mask 定义合法集，必须在一切软操作之前；截断之后的任何改写都破坏核采样的语义。任何实现偏离次序，都要在文档里声明并重测。</p><p><strong>实例化与状态。</strong> 请求到达时按采样配置编译出栈：无状态处理器共享单例；有状态的（重复惩罚、频率计数）每请求实例化，状态随请求走。连续批换槽、抢占恢复时，栈与状态必须跟着序列迁移——丢状态的表现不是报错，是「惩罚悄悄失效」。</p><p><span class="marginnote">常见误区：初学者容易以为惩罚是「配置」而不是「状态」。实际上重复惩罚每生成一个词都要记住这个词出现过没有、出现几次，这份记账本属于具体请求。如果连续批处理把请求 A 挪了个位置却没把记账本一起搬走，惩罚就会算到别人的账上——输出不报错，只是悄悄变味。</span></p><p><strong>批量分派。</strong> 同构栈的请求合并走批处理路径（一张掩码张量加一组稀疏 bias）；异构栈走逐条路径或下推到采样核（<a href="/llm/sampler-kernel">采样器内核</a>）。CPU 上的栈是 decode 的潜在同步点，重叠的教训与<a href="/llm/structured-output-overhead">结构化输出</a>同一条。</p>',11)),(s(),l(A,null,{default:e(()=>[i(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22%E8%AF%B7%E6%B1%82%E9%87%87%E6%A0%B7%E9%85%8D%E7%BD%AE%22%5D%20--%3E%20INST%5B%22%E5%AE%9E%E4%BE%8B%E5%8C%96%E5%A4%84%E7%90%86%E5%99%A8%E6%A0%88%22%5D%0A%20%20INST%20--%3E%20APP%7B%22%E6%89%B9%E5%86%85%E5%90%8C%E6%9E%84%3F%22%7D%0A%20%20APP%20--%3E%7C%E6%98%AF%7C%20BATCH%5B%22%E6%89%B9%E5%A4%84%E7%90%86%E8%B7%AF%E5%BE%84%EF%BC%9A%E5%85%B1%E4%BA%AB%E6%8E%A9%E7%A0%81%E5%BC%A0%E9%87%8F%22%5D%0A%20%20APP%20--%3E%7C%E5%90%A6%7C%20PER%5B%22%E9%80%90%E6%9D%A1%E8%B7%AF%E5%BE%84%20%2F%20%E9%87%87%E6%A0%B7%E6%A0%B8%E5%88%86%E6%B4%BE%22%5D%0A%20%20BATCH%20--%3E%20ORD%5B%22mask%20%E2%86%92%20affine%20%E2%86%92%20%E6%B8%A9%E5%BA%A6%20%E2%86%92%20%E6%88%AA%E6%96%AD%22%5D%0A%20%20PER%20--%3E%20ORD%0A%20%20ORD%20--%3E%20SAMP%5B%22%E9%87%87%E6%A0%B7%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[t("次序契约的正确性可以逐条论证：mask 在前，保证 affine 与截断只在合法集内活动；affine 在温度前，保证「同一 bias 在不同温度下硬度不同」的语义可复现（温度越低同一 \\(b\\) 越接近禁令）；截断最后，保证核的定义域是全部前面的变换都生效后的分布。投机解码下栈还有一个义务：偏置与掩码必须同时进入目标分布与草稿校验的两侧，否则无损接受对的是未偏置的 \\(p\\)——这是 "),E("a",{href:"/llm/logit-bias"},"logit bias 课"),t("的边界在栈上的落点。")],-1)),a[5]||(a[5]=E("p",null,"可观测性是栈的验收面：每步记录「哪个处理器把多少 token 打成 \\(-\\infty\\)、哪些 token 被 affine 移出了核」。线上事故大多不是某个处理器算错，而是两个处理器在同一位置上打架——只有栈快照能定位。",-1)),a[6]||(a[6]=E("p",null,"为什么次序必须钉死，看每个处理器各自假设它前面的分布长什么样：",-1)),(s(),l(A,null,{default:e(()=>[i(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20RAW%5B%22%E5%8E%9F%E5%A7%8B%20logits%3Cbr%2F%3E%E5%85%A8%E4%BD%93%E8%AF%8D%E8%A1%A8%E5%90%88%E6%B3%95%22%5D%20--%3E%20MASK%5B%22mask%3Cbr%2F%3E%E5%81%87%E8%AE%BE%EF%BC%9A%E5%8F%AF%E5%9C%A8%E5%85%A8%E8%A1%A8%E5%88%92%E7%A6%81%E5%8C%BA%22%5D%0A%20%20MASK%20--%3E%20AFF%5B%22affine%20%E6%83%A9%E7%BD%9A%2Fbias%3Cbr%2F%3E%E5%81%87%E8%AE%BE%EF%BC%9A%E5%8F%AA%E5%9C%A8%E5%90%88%E6%B3%95%E9%9B%86%E5%86%85%E5%8A%A0%E5%88%86%E5%87%8F%E5%88%86%22%5D%0A%20%20AFF%20--%3E%20TEMP%5B%22%E6%B8%A9%E5%BA%A6%3Cbr%2F%3E%E5%81%87%E8%AE%BE%EF%BC%9A%E6%94%B9%E7%A1%AC%E5%BA%A6%E4%B8%8D%E6%94%B9%E5%90%88%E6%B3%95%E9%9B%86%22%5D%0A%20%20TEMP%20--%3E%20CUT%5B%22top-k%20%2F%20top-p%20%E6%88%AA%E6%96%AD%3Cbr%2F%3E%E5%81%87%E8%AE%BE%EF%BC%9A%E5%88%86%E5%B8%83%E5%B7%B2%E5%AE%9A%EF%BC%8C%E5%8F%AA%E5%89%AA%E5%B0%BE%E9%83%A8%22%5D%0A%20%20CUT%20--%3E%20SAMP%5B%22%E9%87%87%E6%A0%B7%22%5D%0A%20%20MASK%20-.%20%22%E8%8B%A5%E8%A2%AB%E6%8C%AA%E5%88%B0%E6%88%AA%E6%96%AD%E5%90%8E%22%20.-%3E%20BUG%5B%22%E7%A6%81%E5%8C%BA%E5%8F%AF%E8%83%BD%E6%95%B4%E6%AE%B5%E8%A2%AB%E6%88%AA%E6%8E%89%E6%88%96%E5%A4%8D%E6%B4%BB%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">数字实例：\\(d=|V|=32000\\) 个 logits，若栈里有 12 个无状态处理器、每个都复制一遍张量做原地改写，一步就是约 \\(12 \\times 32000 \\times 4\\) 字节 \\(\\approx 1.5\\) MB 的额外搬运；所以工程上先合并 bias 成一个稀疏表、处理器尽量原地写，而不是无脑堆层数。</span></p><p><span class="marginnote">回归测试要钉到「栈快照等价」：同一请求、同一前缀，逐处理器的中间 logits 与参考实现逐位比对。顺序挪一格，分布就不同——这是最容易过 CI、最容易伤用户的改动。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>栈是兼容性契约：处理器列表与次序的变更要走版本化，评测与线上必须同一版本（<a href="/llm/logit-bias">logit bias 课</a>的「评测线上同一张 \\(b\\)」在栈上是同一句话）。栈长度有性能上限：每处理器每步至少 \\(O(|\\mathcal{V}|)\\) 或稀疏集大小，十几个处理器串联会把 CPU 侧变成屋顶——先合并同类（多个 bias 合成一个稀疏对列表），再谈下推。栈不解决的问题留给后课：序列何时结束是停止语义，流式怎么交付是流式课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>栈契约三要素：操作类型（mask / affine / scaler / truncator）、是否有状态、固定次序。</li><li>次序钉死为 mask → affine → 温度 → 截断 → 采样；偏离须声明并重测。</li><li>有状态处理器属于请求，连续批迁移时状态跟序列走。</li><li>同构栈走批处理路径，异构栈逐条或下推采样核；CPU 侧是同步点。</li><li>投机解码下栈要进目标与草稿两侧；回归测试用栈快照逐位比对。</li><li>出处：据 Transformers 的 LogitsProcessorList 接口与 vLLM、SGLang 等引擎的 logits processor 约定整理；机制零件见 n-gram 阻断、logit bias 与采样各课。</li></ul>',6))])}const F=n(d,[["render",m]]);export{D as __pageData,F as default};
